    "body": "<div class=\"sidebar\" id=\"sidebar\">\n        <div class=\"sidebar-header\">\n            <div class=\"logo\">\n                <i class=\"fas fa-shield-alt\"></i>\n                <h2>MicroSOC</h2>\n            </div>\n            <button class=\"sidebar-toggle\" onclick=\"toggleSidebar()\"><i class=\"fas fa-bars\"></i></button>\n        </div>\n        <div class=\"user-info\">\n            <div class=\"avatar\"><i class=\"fas fa-user-secret\"></i></div>\n            <div class=\"user-details\">\n                <h3 id=\"user-name\">Loading...</h3>\n                <p id=\"user-role\">Loading...</p>\n                <p id=\"user-email\" style=\"font-size: 11px; color: var(--text-secondary); margin-top: 2px;\">Loading...</p>\n            </div>\n        </div>\n        <nav class=\"sidebar-nav\">\n            <ul>\n                <li><a href=\"dashboard.html\"><i class=\"fas fa-tachometer-alt\"></i><span>Dashboard</span></a></li>\n                <li><a href=\"logs.html\"><i class=\"fas fa-stream\"></i><span>Security Logs</span></a></li>\n                <li><a href=\"alerts.html\"><i class=\"fas fa-bell\"></i><span>Alerts</span></a></li>\n                <li><a href=\"incidents.html\"><i class=\"fas fa-exclamation-triangle\"></i><span>Incidents</span></a></li>\n                <li><a href=\"analytics.html\"><i class=\"fas fa-chart-line\"></i><span>Analytics</span></a></li>\n                <li><a href=\"#/audit-logs\"><i class=\"fas fa-clipboard-list\"></i><span>Audit Logs</span></a></li>\n                <li class=\"active\"><a href=\"#/settings\"><i class=\"fas fa-cogs\"></i><span>Settings</span></a></li>\n                <li><a href=\"#\" onclick=\"toggleTheme()\"><i class=\"fas fa-moon\"></i><span>Theme</span></a></li>\n                <li><a href=\"#\" onclick=\"logout()\"><i class=\"fas fa-sign-out-alt\"></i><span>Logout</span></a></li>\n            </ul>\n        </nav>\n    </div>\n\n    <div class=\"main-content\" id=\"main-content\">\n        <header class=\"main-header\">\n            <div class=\"header-left\">\n                <h1><i class=\"fas fa-cogs\"></i> Settings</h1>\n                <p class=\"subtitle\">Threat thresholds, alert rules, and system configs</p>\n            </div>\n            <div class=\"header-right\">\n                <button class=\"btn btn-primary\" data-settings-save><i class=\"fas fa-save\"></i> Save Changes</button>\n            </div>\n        </header>\n\n        <section class=\"feature-panel feature-settings-console settings-page\">\n            <div class=\"feature-panel-header\">\n                <div>\n                    <h2><i class=\"fas fa-sliders-h\"></i> SOC Controls</h2>\n                    <p>Adjust the live guardrails that drive alerts, retention, and defense behavior.</p>\n                </div>\n            </div>\n\n            <div class=\"settings-summary-grid\" data-settings-summary></div>\n            <div class=\"settings-grid\">\n                <section class=\"settings-card\" data-settings-section=\"thresholds\">\n                    <div class=\"settings-card-header\">\n                        <h3><i class=\"fas fa-bolt\"></i> Threat Thresholds</h3>\n                        <p>Severity cutoffs for automated detection.</p>\n                    </div>\n                    <div class=\"settings-fields\" data-threshold-fields></div>\n                </section>\n                <section class=\"settings-card\" data-settings-section=\"rules\">\n                    <div class=\"settings-card-header\">\n                        <h3><i class=\"fas fa-bell\"></i> Alert Rules</h3>\n                        <p>Automation and escalation behavior for alerts.</p>\n                    </div>\n                    <div class=\"settings-fields\" data-rule-fields></div>\n                </section>\n                <section class=\"settings-card\" data-settings-section=\"configs\">\n                    <div class=\"settings-card-header\">\n                        <h3><i class=\"fas fa-server\"></i> System Configs</h3>\n                        <p>Retention, refresh cadence, and platform behavior.</p>\n                    </div>\n                    <div class=\"settings-fields\" data-config-fields></div>\n                </section>\n            </div>\n        </section>\n    </div>",
